// guards/migration-guard.ts
// Every migration must be reversible: a real down step, and a
// named backup when the up step destroys data that a down step
// cannot bring back.
// Card P23 (Chapter 8). Placement: commit and build. Kind:
// sensor, computational.
// Retire when: migrations are generated by a tool that always
// emits a down step and takes a backup before destructive
// changes.
import { readFileSync } from 'node:fs';
import { basename } from 'node:path';
import { listFiles } from './lib/files.ts';
import { isMain, report } from './lib/log.ts';

const DIR = 'app/src/db/migrations';
const DESTRUCTIVE =
  /\b(DROP\s+TABLE|DROP\s+COLUMN|DELETE\s+FROM|TRUNCATE)\b/i;
const BACKUP = /^--\s*backup:\s*\S+/m;

const NO_DOWN =
  'Fix: add a "-- migrate:down" section with SQL that undoes ' +
  'the up step exactly, and run it against a copy of the ' +
  'database before you ask for review.';
const NO_BACKUP =
  'Fix: a down step cannot restore deleted rows. Copy the ' +
  'data first (for example CREATE TABLE clients_backup AS ' +
  'SELECT ...) and declare it with a "-- backup: <table>" ' +
  'line.';

// The SQL of a section with comments and blank lines removed.
function section(
  sql: string,
  start: string,
  end?: string,
): string | undefined {
  const from = sql.indexOf(start);
  if (from === -1) return undefined;
  const to = end ? sql.indexOf(end, from) : -1;
  const stop = to === -1 ? undefined : to;
  const body = sql.slice(from + start.length, stop);
  const isSql = (line: string) => !/^\s*(--.*)?$/.test(line);
  return body.split('\n').filter(isSql).join('\n');
}

export function checkMigration(
  file: string,
  sql: string,
): string[] {
  const name = basename(file);
  const up = section(sql, '-- migrate:up', '-- migrate:down');
  const down = section(sql, '-- migrate:down');
  const problems: string[] = [];
  if (!down) {
    problems.push(`${name} has no down step.\n${NO_DOWN}`);
  }
  const destroys = DESTRUCTIVE.exec(up ?? '')?.[1];
  if (destroys && !BACKUP.test(sql)) {
    const what = `${name} destroys data (${destroys})`;
    problems.push(`${what} and names no backup.\n${NO_BACKUP}`);
  }
  return problems;
}

if (isMain(import.meta.url)) {
  const files = listFiles(DIR, ['.sql']);
  const problems = files.flatMap((file) =>
    checkMigration(file, readFileSync(file, 'utf8')),
  );
  const ok = `${files.length} migrations, all reversible`;
  report('migration-guard', problems, ok);
}
